// Run against an isolated preview only. Fixtures are generated by test_icon_images.
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { homedir } from 'node:os';
import path from 'node:path';
import { mkdir, writeFile } from 'node:fs/promises';
const require = createRequire(import.meta.url);
let playwright;
try { playwright = require('playwright'); }
catch { playwright = require(path.join(homedir(), '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright')); }
const base = new URL(process.argv[2] || 'http://127.0.0.1:8875/');
if (!['127.0.0.1', 'localhost'].includes(base.hostname)) throw new Error('Use an isolated local preview.');
const out = path.resolve('output/icons-e2e');
await mkdir(out, { recursive: true });
const browser = await playwright.chromium.launch({ channel: 'msedge', headless: true });
const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
const report = { checks: [], errors: [] };
page.on('pageerror', (error) => report.errors.push(error.message));
async function api(kind, method = 'GET', body) {
    const response = await fetch(new URL('/api/' + kind, base), { method,
        headers: { Origin: base.origin, 'X-Requested-With': 'homelab-dashboard', 'X-Icon-Format-Version': '2', 'Content-Type': 'application/json' },
        ...(body ? { body: JSON.stringify(body) } : {}) });
    assert.equal(response.status, 200);
    return response.json();
}
const original = await Promise.all(['favicon', 'page-icon'].map((kind) => api(kind)));
if (original.some((state) => state.configured)) throw new Error('Use an empty icon preview to avoid overwriting test data.');
async function check(name, task) { await task(); report.checks.push(name); console.log('PASS', name); }
async function editor(kind) {
    await page.locator('#page-settings-button').click();
    await page.locator(`#${kind}-editor-button`).click();
    await page.waitForFunction((id) => document.getElementById(id).open, kind + '-dialog');
    await page.locator(`#${kind}-select-button`).waitFor({ state: 'visible' });
}
async function close(kind) {
    await page.locator(`#${kind}-close`).click();
    await page.waitForFunction((id) => !document.getElementById(id).open, kind + '-dialog');
}
async function importFile(kind, file) {
    await page.locator(`#${kind}-file-input`).setInputFiles(file);
    await page.waitForFunction((id) => !document.getElementById(id).disabled, kind + '-save-button');
}
async function saved(kind, file) {
    await importFile(kind, file);
    await page.locator(`#${kind}-save-button`).click();
    await page.waitForFunction((id) => document.getElementById(id).textContent.includes('已保存'), kind + '-status');
    return api(kind);
}
async function artwork(fragment) {
    await page.waitForFunction((text) => [...document.querySelectorAll('[data-site-icon] img')].every((image) => image.complete && image.naturalWidth && image.src.includes(text)), fragment);
}
try {
    await page.goto(base.href);
    await page.waitForFunction(() => document.getElementById('page-icon-select-button').disabled === false);
    await page.waitForFunction(() => !document.documentElement.classList.contains('intro-first'));
    const baseline = await page.locator('.hero-title').boundingBox();
    for (const kind of ['favicon', 'page-icon']) {
        await editor(kind);
        for (const extension of ['png', 'jpg', 'webp', 'ico', 'svg']) {
            await check(`${kind} ${extension} preview/save`, async () => {
                const before = await api(kind);
                await importFile(kind, path.join(out, 'static.' + extension));
                assert.deepEqual(await api(kind), before);
                await page.locator(`#${kind}-save-button`).click();
                await page.waitForFunction((id) => document.getElementById(id).textContent.includes('已保存'), kind + '-status');
                const state = await api(kind);
                assert.equal(state.mimeType, extension === 'svg' ? 'image/svg+xml' : 'image/png');
                assert.equal(state.animated, false);
                if (kind === 'favicon') assert.equal(await page.locator('link[data-managed-favicon]').getAttribute('type'), state.mimeType);
                else await artwork(state.contentHash);
            });
        }
        await close(kind);
    }
    for (const extension of ['apng', 'webp', 'gif']) {
        await check(`page animation ${extension}, modal poster and reduced motion`, async () => {
            const faviconBefore = await api('favicon');
            await editor('page-icon');
            const state = await saved('page-icon', path.join(out, 'animated.' + extension));
            assert.equal(state.animated, true);
            await artwork(state.posterHash);
            await close('page-icon');
            await artwork(state.contentHash);
            await page.emulateMedia({ reducedMotion: 'reduce' });
            await artwork(state.posterHash);
            const css = await page.locator('.corner-badge').first().evaluate((el) => getComputedStyle(el).animationName);
            assert.equal(css, 'none');
            await page.emulateMedia({ reducedMotion: 'no-preference' });
            await artwork(state.contentHash);
            assert.deepEqual(await api('favicon'), faviconBefore);
        });
    }
    await check('animated favicon is a square static PNG', async () => {
        await editor('favicon');
        const state = await saved('favicon', path.join(out, 'animated.gif'));
        assert.equal(state.animated, false);
        assert.equal(state.width, state.height);
        assert.equal(state.mimeType, 'image/png');
        await close('favicon');
    });
    await check('reload and responsive corners', async () => {
        const state = await api('page-icon');
        await page.reload(); await artwork(state.contentHash);
        assert.equal(await page.locator('.corner-badge').first().isVisible(), true);
        const after = await page.locator('.hero-title').boundingBox();
        assert.equal(after.y, baseline.y); assert.equal(after.height, baseline.height);
        for (const [width, height, visible] of [[1440,900,true],[1366,768,false],[390,844,false],[1600,2000,false]]) {
            await page.setViewportSize({ width, height });
            assert.equal(await page.locator('.corner-badge').first().isVisible(), visible);
        }
        await page.setViewportSize({ width: 1920, height: 1080 });
        await page.screenshot({ path: path.join(out, 'animated-desktop.png') });
    });
    await check('invalid import and stale previews keep the saved icon', async () => {
        await editor('page-icon');
        const state = await api('page-icon');
        await page.locator('#page-icon-file-input').setInputFiles({ name: 'bad.png', mimeType: 'image/png', buffer: Buffer.from('bad') });
        await page.waitForFunction(() => document.getElementById('page-icon-status').dataset.kind === 'error');
        assert.deepEqual(await api('page-icon'), state);
        await page.route('**/api/page-icon/preview', async (route) => {
            if (route.request().postDataJSON().fileName.endsWith('.apng')) await new Promise((resolve) => setTimeout(resolve, 500));
            await route.continue();
        });
        await page.locator('#page-icon-file-input').setInputFiles(path.join(out, 'animated.apng'));
        await page.locator('#page-icon-file-input').setInputFiles(path.join(out, 'static.png'));
        await page.waitForFunction(() => document.getElementById('page-icon-state-label').textContent.includes('static.png'));
        await page.waitForTimeout(1000);
        assert.match(await page.locator('#page-icon-state-label').textContent(), /static.png/);
        await page.unroute('**/api/page-icon/preview');
        await close('page-icon');
    });
    await check('save failure retains the current icon and retryable draft', async () => {
        await editor('page-icon');
        const before = await api('page-icon');
        await importFile('page-icon', path.join(out, 'static.png'));
        await page.route('**/api/page-icon', async (route) => {
            if (route.request().method() === 'PATCH') await route.fulfill({ status: 503, contentType: 'application/json', body: '{"error":"test_unavailable"}' });
            else await route.continue();
        });
        await page.locator('#page-icon-save-button').click();
        await page.waitForFunction(() => document.getElementById('page-icon-status').dataset.kind === 'error' && !document.getElementById('page-icon-save-button').disabled);
        assert.match(await page.locator('#page-icon-state-label').textContent(), /static.png/);
        assert.deepEqual(await api('page-icon'), before);
        await page.unroute('**/api/page-icon');
        await page.locator('#page-icon-save-button').click();
        await page.waitForFunction(() => document.getElementById('page-icon-status').textContent.includes('已保存'));
        await close('page-icon');
    });
    await check('old backend retains SVG support and explains other formats', async () => {
        const old = { version: 1, configured: false, updatedAt: null, contentHash: null };
        await page.route('**/api/favicon', async (route) => route.request().method() === 'GET'
            ? route.fulfill({ contentType: 'application/json', body: JSON.stringify(old) }) : route.continue());
        await editor('favicon');
        await page.waitForTimeout(100);
        await page.locator('#favicon-file-input').setInputFiles(path.join(out, 'static.png'));
        await page.waitForFunction(() => document.getElementById('favicon-status').textContent.includes('升级后端'));
        await importFile('favicon', path.join(out, 'static.svg'));
        assert.equal(await page.locator('#favicon-preview svg').count(), 1);
        await close('favicon');
        await page.unroute('**/api/favicon');
        await page.reload();
        await page.waitForFunction(() => !document.getElementById('favicon-select-button').disabled);
    });
    await check('UI removal restores default page badge and removes favicon', async () => {
        for (const kind of ['page-icon','favicon']) {
            await editor(kind);
            await page.locator(`#${kind}-remove-button`).click();
            await page.locator(`#${kind}-remove-confirm`).click();
            await page.waitForFunction((id) => document.getElementById(id).textContent.includes('已恢复') || document.getElementById(id).textContent.includes('已移除'), kind + '-status');
            await close(kind);
        }
        await artwork('/assets/icons/homepage-badge.svg');
        assert.equal(await page.locator('link[data-managed-favicon]').count(), 0);
        await page.screenshot({ path: path.join(out, 'default-desktop.png') });
    });
    assert.deepEqual(report.errors, []);
} finally {
    await Promise.all(['favicon', 'page-icon'].map((kind) => api(kind, 'PATCH', { version: 2, icon: null })));
    await writeFile(path.join(out, 'report.json'), JSON.stringify(report, null, 2));
    await browser.close();
}
